/* mqtt_handler.c - IoT device message handler for sensor telemetry */
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_TOPIC_LEN 256
#define MAX_PAYLOAD_LEN 4096
#define MAX_HANDLERS 64

typedef struct msg_context {
    char topic[MAX_TOPIC_LEN];
    char *payload;
    size_t payload_len;
    int ref_count;
    void (*cleanup)(struct msg_context *);
    struct msg_context *next;
} msg_context_t;

typedef struct {
    msg_context_t *active_contexts[MAX_HANDLERS];
    pthread_mutex_t lock;
    int handler_count;
    volatile int shutting_down;
} handler_registry_t;

static handler_registry_t g_registry = { .lock = PTHREAD_MUTEX_INITIALIZER };

msg_context_t *create_context(const char *topic, const char *payload, size_t len) {
    msg_context_t *ctx = (msg_context_t *)malloc(sizeof(msg_context_t));
    if (!ctx) return NULL;
    strncpy(ctx->topic, topic, MAX_TOPIC_LEN - 1);
    ctx->topic[MAX_TOPIC_LEN - 1] = '\0';
    ctx->payload = (char *)malloc(len + 1);
    if (!ctx->payload) { free(ctx); return NULL; }
    memcpy(ctx->payload, payload, len);
    ctx->payload[len] = '\0';
    ctx->payload_len = len;
    ctx->ref_count = 1;
    ctx->cleanup = NULL;
    ctx->next = NULL;
    return ctx;
}

void release_context(msg_context_t *ctx) {
    if (!ctx) return;
    ctx->ref_count--;
    if (ctx->ref_count <= 0) {
        if (ctx->cleanup) ctx->cleanup(ctx);
        free(ctx->payload);
        free(ctx);
    }
}

/* BUG: Race condition - context can be freed by dispatch thread while
   still referenced by the async processing callback */
void *async_process_message(void *arg) {
    msg_context_t *ctx = (msg_context_t *)arg;
    /* Simulate processing delay */
    usleep(100000);

    /* USE-AFTER-FREE: ctx may have been freed by handle_disconnect() */
    if (ctx->payload_len > 0) {
        /* Attacker-controlled payload used as function pointer via vtable confusion */
        if (ctx->cleanup) {
            ctx->cleanup(ctx);  /* Arbitrary code execution if heap is groomed */
        }
        printf("Processed: %s -> %.*s\n", ctx->topic, (int)ctx->payload_len, ctx->payload);
    }
    release_context(ctx);
    return NULL;
}

void handle_message(const char *topic, const char *payload, size_t len) {
    pthread_t tid;
    msg_context_t *ctx = create_context(topic, payload, len);
    if (!ctx) return;

    pthread_mutex_lock(&g_registry.lock);
    /* Register without incrementing ref_count - BUG */
    int slot = g_registry.handler_count % MAX_HANDLERS;
    g_registry.active_contexts[slot] = ctx;
    g_registry.handler_count++;
    pthread_mutex_unlock(&g_registry.lock);

    /* Spawn async handler - ctx ref_count is still 1 */
    pthread_create(&tid, NULL, async_process_message, ctx);
    pthread_detach(tid);
}

void handle_disconnect(int client_id) {
    pthread_mutex_lock(&g_registry.lock);
    for (int i = 0; i < MAX_HANDLERS; i++) {
        if (g_registry.active_contexts[i]) {
            /* Free all contexts for disconnected client without checking
               if async_process_message is still using them */
            release_context(g_registry.active_contexts[i]);
            g_registry.active_contexts[i] = NULL;
        }
    }
    pthread_mutex_unlock(&g_registry.lock);
}

int main(int argc, char *argv[]) {
    /* Simulated MQTT message arrival */
    handle_message("sensors/temp/1", "{\"value\": 23.5}", 16);
    handle_message("sensors/humidity/1", "{\"value\": 65}", 14);

    /* Simulated abrupt disconnect triggers UAF */
    usleep(50000);
    handle_disconnect(1);

    /* Wait for async handlers to trigger UAF */
    usleep(200000);
    return 0;
}
